mapper.select:
select unQualified, total, (case total when 0 THEN 0 /*总数为0时，合格率为0*/ else ROUND((1-(unQualified/total))*100,2) end)as rate, pageType from( /*1 证件类型合格率*/ select count(temp.SUBMIT_STATUS) as total, count(temp.SUBMIT_STATUS) - nvl(sum(temp.lateNums),0) as unQualified, '1' as pageType /*1 证件类型*/ from( select case when ces.PERSONAL_IDENTIFY_TYPE in ('00','01') then 1 else 0 end lateNums, /*统计不符合条件数*/ ces.SUBMIT_STATUS from CHB_EQU_SUB ces where ces.STATUS in ('01','02') and ces.SUBMIT_STATUS in ('02','03') and ces.HOLDER_MARK = '01' and ces.HOLDER_TYPE in ('01','02','03')
#{orgCode,jdbcType=VARCHAR}
and trunc(ces.SUBMIT_TIME) <= to_date(#{searchDate},'yyyy-MM-dd') ) temp
union all /*2 证件匹配合格率*/ select temp2.total as total, temp1.unQualified, '2' as pageType /*2 证件匹配*/ from( select nvl(sum(counts),0) as unQualified from ( select ces1.PERSONAL_IDENTIFY_TYPE, ces1.INSTITUTION_IDENTIFY_TYPE, ces1.IDENTIFY_NUMBER, count(1) counts from CHB_EQU_SUB ces1 where ces1.STATUS in ('01','02') and ces1.SUBMIT_STATUS in ('02','03')
#{orgCode,jdbcType=VARCHAR}
and trunc(ces1.SUBMIT_TIME) <= to_date(#{searchDate},'yyyy-MM-dd') group by ces1.PERSONAL_IDENTIFY_TYPE, ces1.INSTITUTION_IDENTIFY_TYPE, ces1.IDENTIFY_NUMBER having count(1) > 1) ) temp1,( select count(1) total from CHB_EQU_SUB ces2 where ces2.STATUS in ('01','02') and ces2.SUBMIT_STATUS in ('02','03')
#{orgCode,jdbcType=VARCHAR}
and trunc(ces2.SUBMIT_TIME) <= to_date(#{searchDate},'yyyy-MM-dd') ) temp2
union all /*3 及时性合格率*/ select count(temp.SEND_STATUS) as total, nvl(sum(temp.lateNums),0) as unQualified, '3' as pageType /*3 及时性*/ from( select /*+parallel(ciis,4)*/ case when ciis.SUBMIT_TIME > ciis.SUBMIT_DEADLINE then 1 else 0 end lateNums, /*统计不符合条件数*/ ciis.SEND_STATUS from CHB_INVESTHOLD_INFO_SUB ciis where ciis.STATUS in ('01','02') and ciis.SEND_STATUS in ('02','03')
#{orgCode,jdbcType=VARCHAR}
and trunc(ciis.SUBMIT_TIME) <= to_date(#{searchDate},'yyyy-MM-dd') ) temp )

select ces.INDENTIFY_MARK indentifyMark, ces.HOLDER_MARK holderMark, ces.HOLDER_TYPE holderType, ces.PERSONAL_IDENTIFY_TYPE personalIdentifyType from CHB_EQU_SUB ces where ces.STATUS in ('01','02') and ces.SUBMIT_STATUS in ('02','03') and ces.HOLDER_MARK = '01' and ces.HOLDER_TYPE in ('01','02','03')
#{orgCode,jdbcType=VARCHAR}
and to_date(to_char(ces.SUBMIT_TIME, 'yyyy-MM-dd'), 'yyyy-MM-dd') <= to_date(#{searchDate},'yyyy-MM-dd') and ces.PERSONAL_IDENTIFY_TYPE not in ('00','01')

with temp as ( select ces1.PERSONAL_IDENTIFY_TYPE, ces1.INSTITUTION_IDENTIFY_TYPE, ces1.IDENTIFY_NUMBER, count(1) counts from CHB_EQU_SUB ces1 where ces1.STATUS in ('01','02') and ces1.SUBMIT_STATUS in ('02','03')
#{orgCode,jdbcType=VARCHAR}
and to_date(to_char(ces1.SUBMIT_TIME, 'yyyy-MM-dd'), 'yyyy-MM-dd') <= to_date(#{searchDate},'yyyy-MM-dd') group by ces1.PERSONAL_IDENTIFY_TYPE, ces1.INSTITUTION_IDENTIFY_TYPE, ces1.IDENTIFY_NUMBER having count(1) > 1 )
select ces.REGIST_BANK_CODE registBankCode, ces.INDENTIFY_MARK indentifyMark, ces.PERSONAL_IDENTIFY_TYPE personalIdentifyType, ces.INSTITUTION_IDENTIFY_TYPE institutionIdentifyType, nvl(ces.PERSONAL_IDENTIFY_TYPE,ces.INSTITUTION_IDENTIFY_TYPE) identifyType, ces.IDENTIFY_NUMBER identifyNumber, ces.HOLDER_NAME holderName from CHB_EQU_SUB ces INNER join temp on nvl(ces.personal_identify_type,'0')=nvl(temp.personal_identify_type,'0') and nvl(ces.institution_identify_type,'0')=nvl(temp.institution_identify_type,'0') and ces.identify_number=temp.identify_number where ces.STATUS in ('01','02') and ces.SUBMIT_STATUS in ('02','03') and to_date(to_char(ces.SUBMIT_TIME, 'yyyy-MM-dd'), 'yyyy-MM-dd') <= to_date(#{searchDate},'yyyy-MM-dd')
#{orgCode,jdbcType=VARCHAR}
order by identifyType asc ,identifyNumber asc

select ciis.PRD_REGIST_CODE prdRegistCode, ciis.INDENTIFY_MARK indentifyMark, ciis.HOLD_DATE holdDate, ciis.SEND_STATUS sendStatus, ciis.SUBMIT_TIME submitTime from CHB_INVESTHOLD_INFO_SUB ciis where ciis.STATUS in ('01','02') and ciis.SEND_STATUS in ('02','03') and ciis.SUBMIT_TIME > ciis.SUBMIT_DEADLINE
#{orgCode,jdbcType=VARCHAR}
and to_date(to_char(ciis.SUBMIT_TIME, 'yyyy-MM-dd'), 'yyyy-MM-dd') <= to_date(#{searchDate},'yyyy-MM-dd')

mapper.sql:
WITH END_SUB AS ( SELECT PROD_ID, MDATE FROM ( SELECT CHB_PRD_END_SUB.PROD_ID, CHB_PRD_END_SUB.MDATE, CHB_PRD_END_SUB.STATUS, ROW_NUMBER() over( partition BY CHB_PRD_END_SUB.PROD_ID ORDER BY CHB_PRD_END_SUB.UPDATE_TIME DESC) AS rowno FROM CHB_PRD_END_SUB
#{orgCode,jdbcType=VARCHAR}
) WHERE rowno = 1 AND STATUS != #{statusDel,jdbcType=VARCHAR} )

WITH OBJREC AS ( SELECT PROD_REGIST_CODE, SINGLE_TOTAL, LEGAL_TOTAL, UNLEGAL_TOTAL, VDATE FROM ( SELECT A.PROD_REGIST_CODE, A.SINGLE_TOTAL, A.LEGAL_TOTAL, A.UNLEGAL_TOTAL, B.VDATE, A.STATUS, ROW_NUMBER() over( partition BY A.PROD_REGIST_CODE ORDER BY A.UPDATE_TIME DESC) AS rowno FROM CHB_PRD_RAISETOT_SUB A LEFT JOIN CHB_PRD_BASEINFO B ON
A.PROD_ID = B.PROD_ID WHERE TO_DATE(TO_CHAR(B.VDATE, 'yyyy-MM-dd'), 'yyyy-MM-dd') = TO_DATE(#{searchDate,jdbcType=VARCHAR},'yyyy-MM-dd')
#{orgCode,jdbcType=VARCHAR}
) WHERE rowno = 1 AND STATUS != #{statusDel,jdbcType=VARCHAR} )
